**What this code covers**

- Monotonic; only rate() makes sense.
- Goes up and down; read directly.
- Prom_metrics.py - runnable; Prometheus-style metric registry + minimal PromQL parser mock
- PromQL mock: parse and evaluate trivial selectors + sum()
- Match: sum(<metric>{label="v"}) by (k) OR <metric>{label="v"}

**Defines:** `Counter`, `Gauge`, `Registry`, `PromQLMock`

```python
# prom_metrics.py - runnable; Prometheus-style metric registry + minimal PromQL parser mock
from collections import defaultdict
from typing import Callable
import re, time

class Counter:
    """Monotonic; only rate() makes sense."""
    def __init__(self, name: str, help_text: str):
        self.name, self.help = name, help_text
        self._vals: dict[tuple, float] = defaultdict(float)
    def inc(self, labels: dict | None = None, amt: float = 1.0):
        key = tuple(sorted((labels or {}).items()))
        self._vals[key] += amt
    def expose(self) -> list[str]:
        out = [f"# HELP {self.name} {self.help}", f"# TYPE {self.name} counter"]
        for k, v in sorted(self._vals.items()):
            lbl = "{" + ",".join(f'{n}="{val}"' for n, val in k) + "}" if k else ""
            out.append(f"{self.name}{lbl} {v}")
        return out

class Gauge:
    """Goes up and down; read directly."""
    def __init__(self, name: str, help_text: str):
        self.name, self.help = name, help_text
        self._vals: dict[tuple, float] = {}
    def set(self, value: float, labels: dict | None = None):
        key = tuple(sorted((labels or {}).items()))
        self._vals[key] = value
    def expose(self) -> list[str]:
        out = [f"# HELP {self.name} {self.help}", f"# TYPE {self.name} gauge"]
        for k, v in sorted(self._vals.items()):
            lbl = "{" + ",".join(f'{n}="{val}"' for n, val in k) + "}" if k else ""
            out.append(f"{self.name}{lbl} {v}")
        return out

class Registry:
    def __init__(self): self._metrics: list = []
    def register(self, m): self._metrics.append(m); return m
    def render(self) -> str:
        lines: list[str] = []
        for m in self._metrics: lines.extend(m.expose())
        return "\n".join(lines) + "\n"

# ---- PromQL mock: parse and evaluate trivial selectors + sum() ----
class PromQLMock:
    def __init__(self, reg: Registry): self.reg = reg
    def query(self, expr: str) -> list[tuple[str, float]]:
        # match: sum(<metric>{label="v"}) by (k)  OR  <metric>{label="v"}
        m = re.match(r'^sum\((\w+)\s*(?:\{([^}]*)\})?\)\s*by\s*\(([^)]+)\)$', expr.strip())
        if m:
            metric, _, grp = m.groups()
            return self._sum_by(metric, grp.strip().split(","))
        m = re.match(r'^(\w+)\s*(?:\{([^}]*)\})?$', expr.strip())
        if m:
            metric, _ = m.groups()
            return self._select(metric)
        raise ValueError(f"unsupported PromQL: {expr}")
    def _select(self, metric: str) -> list[tuple[str, float]]:
        out = []
        for met in self.reg._metrics:
            if met.name == metric:
                for k, v in met._vals.items():
                    lbl = "{" + ",".join(f'{n}="{val}"' for n, val in k) + "}" if k else ""
                    out.append((lbl, v))
        return out
    def _sum_by(self, metric: str, groups: list[str]) -> list[tuple[str, float]]:
        buckets: dict[str, float] = defaultdict(float)
        for met in self.reg._metrics:
            if met.name != metric: continue
            for k, v in met._vals.items():
                ld = dict(k)
                key = "{" + ",".join(f'{g}="{ld.get(g,"")}"' for g in groups) + "}"
                buckets[key] += v
        return sorted(buckets.items())

if __name__ == "__main__":
    reg = Registry()
    reqs = reg.register(Counter("http_requests_total", "Total HTTP requests"))
    in_flight = reg.register(Gauge("http_in_flight", "In-flight HTTP requests"))

    reqs.inc({"route": "/checkout", "status": "200"})
    reqs.inc({"route": "/checkout", "status": "200"}, 4)
    reqs.inc({"route": "/checkout", "status": "500"})
    reqs.inc({"route": "/api",      "status": "200"}, 12)
    in_flight.set(7, {"route": "/checkout"})
    in_flight.set(3, {"route": "/api"})

    print("--- /metrics exposition ---")
    print(reg.render())

    q = PromQLMock(reg)
    print("--- PromQL: http_requests_total ---")
    print(q.query("http_requests_total"))
    print("--- PromQL: sum(http_requests_total) by (route) ---")
    print(q.query('sum(http_requests_total) by (route)'))
```
